const CEFR_LEVELS=['A1','A2','B1','B2','C1','C2'];
const grammarTopics=[
 {id:'present',icon:'☀️',title:'Present tenses',lv:'Tagadnes laiki',rules:[
  'A1: Use Present Simple for routines and facts: “I work on Mondays.”',
  'A2: Contrast Present Simple with Present Continuous: routine vs happening now.',
  'B1: Use Present Perfect for past actions connected to now: “I have finished.”',
  'B2: Contrast Present Perfect Simple and Continuous: result vs duration/activity.',
  'C1: Use present forms flexibly in narrative, commentary and future schedules.',
  'C2: Control subtle aspect choices to foreground result, process, repetition or temporary states.'
 ],examples:['I usually start at nine.','I am working from home today.','I have lived here for three years.'],tip:'Look for time meaning first: routine, now, experience/result, or duration.'},
 {id:'past',icon:'🕰️',title:'Past tenses',lv:'Pagātnes laiki',rules:[
  'A1: Past Simple describes finished past events: “I visited Riga yesterday.”',
  'A2: Past Continuous describes an action in progress: “I was cooking when you called.”',
  'B1: Use Past Perfect for the earlier of two past events.',
  'B2: Combine past tenses to build clear narrative sequence and background.',
  'C1: Use past forms for distancing, politeness and hypothetical meaning as well as time.',
  'C2: Shift tense and aspect deliberately to control viewpoint and narrative emphasis.'
 ],examples:['We arrived at six.','It was raining when I left.','She had already gone when I called.'],tip:'Put events on a timeline: background → main event → earlier event.'},
 {id:'future',icon:'🔭',title:'Future forms',lv:'Nākotnes formas',rules:[
  'A1: Use “will” for simple predictions and spontaneous decisions.',
  'A2: Use “going to” for plans/evidence and Present Continuous for arrangements.',
  'B1: Choose between will, going to, Present Continuous and Present Simple by meaning.',
  'B2: Use Future Continuous and Future Perfect for actions in progress or completed by a future point.',
  'C1: Express probability and future-in-the-past with precise modal and tense choices.',
  'C2: Use future forms strategically for stance, prediction strength and formal planning.'
 ],examples:['I will call you later.','We are meeting at 7 p.m.','By Friday, I will have finished.'],tip:'English has several future forms; choose by intention, arrangement, schedule or prediction.'},
 {id:'tenses',icon:'🧭',title:'Tense review',lv:'Laiku pārskats',rules:[
  'A1: Distinguish now, routine and finished past.',
  'A2: Add actions in progress and basic future plans.',
  'B1: Connect past and present with Present Perfect and sequence past events accurately.',
  'B2: Control perfect and continuous aspects across past, present and future.',
  'C1: Maintain tense consistency in long explanations, reports and stories.',
  'C2: Use tense shifts intentionally for rhetoric, narrative viewpoint and nuanced meaning.'
 ],examples:['I work / I am working / I worked.','I have worked / I had worked / I will have worked.'],tip:'Do not learn tense names only; connect each form to a time relationship and speaker purpose.'},
 {id:'articles',icon:'🧩',title:'Articles',lv:'Artikuli',rules:[
  'A1: Use a/an for one non-specific countable noun and the for something specific.',
  'A2: Learn common zero-article uses with plurals and uncountable nouns in general statements.',
  'B1: Use articles with places, institutions, meals, transport and common fixed expressions.',
  'B2: Choose articles based on shared knowledge, first/second mention and classification.',
  'C1: Control article choice with abstract nouns, institutions and complex noun phrases.',
  'C2: Use or omit articles for subtle discourse framing and stylistic emphasis.'
 ],examples:['I bought a book. The book is excellent.','Life is short.','She went to school.'],tip:'Ask: countable? singular? specific to the listener? mentioned before?'},
 {id:'prepositions',icon:'📍',title:'Prepositions',lv:'Prievārdi',rules:[
  'A1: Learn core place/time forms: in, on, at, to, from.',
  'A2: Add movement and common adjective/verb combinations.',
  'B1: Learn dependent prepositions as chunks: interested in, depend on, responsible for.',
  'B2: Contrast near-synonyms such as by/with, during/for, in/within.',
  'C1: Use prepositional phrases precisely in formal and academic English.',
  'C2: Master idiomatic and register-sensitive preposition choices.'
 ],examples:['at 7 o’clock','on Monday','in September','interested in music'],tip:'Many prepositions are lexical chunks. Save the whole phrase, not just the preposition.'},
 {id:'adverbs',icon:'⚡',title:'Adverbs',lv:'Apstākļa vārdi',rules:[
  'A1: Use frequency adverbs: always, usually, often, sometimes, never.',
  'A2: Form many manner adverbs with -ly and place them naturally.',
  'B1: Use degree adverbs: quite, rather, extremely, hardly, nearly.',
  'B2: Use sentence adverbs to show attitude: fortunately, apparently, surprisingly.',
  'C1: Position adverbs for focus and emphasis without creating ambiguity.',
  'C2: Use stance and linking adverbials to shape argument and register.'
 ],examples:['I usually walk to work.','She spoke quietly.','Apparently, the train was cancelled.'],tip:'Adverb position changes emphasis; frequency adverbs usually go before the main verb but after “be”.'},
 {id:'adjectives',icon:'🎨',title:'Adjectives',lv:'Īpašības vārdi',rules:[
  'A1: Use basic adjective + noun and be + adjective patterns.',
  'A2: Compare with -er/-est and more/most.',
  'B1: Learn adjective order and -ed/-ing contrasts: bored/boring.',
  'B2: Use gradable/non-gradable adjectives and strong modifiers.',
  'C1: Build concise complex noun phrases with participial adjectives.',
  'C2: Choose precise evaluative adjectives and control connotation/register.'
 ],examples:['a small red car','more interesting','I was bored; the film was boring.'],tip:'Opinion usually comes before size, age, shape, colour, origin, material and purpose.'},
 {id:'conditionals',icon:'🔀',title:'Conditionals',lv:'Nosacījuma teikumi',rules:[
  'A1: Use if + Present, will for likely future results.',
  'A2: Use zero conditional for facts and first conditional for real possibilities.',
  'B1: Use second conditional for unreal/unlikely present or future situations.',
  'B2: Use third and mixed conditionals for unreal past results and cross-time relationships.',
  'C1: Use inversion and alternative conditional markers: had, were, should, provided that.',
  'C2: Manipulate conditionals for politeness, rhetoric, concession and counterfactual nuance.'
 ],examples:['If it rains, we will stay home.','If I had more time, I would study Latvian.','If I had left earlier, I would have caught the train.'],tip:'Identify whether the condition is factual, possible, unreal now, or unreal in the past.'},
 {id:'complex',icon:'🔗',title:'Complex sentences',lv:'Salikti teikumi',rules:[
  'A1: Join simple ideas with and, but, because and so.',
  'A2: Add when, if, before, after, although and basic relative clauses.',
  'B1: Use defining relative clauses and a wider range of subordinators.',
  'B2: Use non-defining relative clauses, participle clauses and varied linking devices.',
  'C1: Control clause embedding, information flow and punctuation in long sentences.',
  'C2: Vary clause structure for sophisticated argument, emphasis and rhythm while keeping clarity.'
 ],examples:['I stayed home because I was tired.','The woman who called you is my manager.','Although it was late, we continued working.'],tip:'A complex sentence is useful only if the relationship between ideas stays clear.'}
,
{"id": "modals", "icon": "🎛️", "title": "Modal verbs & nuance", "lv": "Modālie darbības vārdi", "rules": ["A1: Use can/can't for basic ability and permission.", "A2: Add should, must, have to and may for advice, obligation and possibility.", "B1: Contrast must, have to, should, might and could by strength and meaning.", "B2: Use modal perfect forms such as should have, might have and must have.", "C1: Express probability, criticism, speculation and politeness with precise modal choices.", "C2: Control modality for stance, diplomacy and evidential nuance in professional and academic English."], "examples": ["You should check the details.", "She might have missed the train.", "That must have been difficult."], "tip": "Think about strength: certainty, possibility, advice, obligation or criticism."},
{"id": "passive", "icon": "🔄", "title": "Passive & causative", "lv": "Ciešamā kārta un causative", "rules": ["A1: Recognise simple passive patterns: is made, was built.", "A2: Use present and past passive when the action matters more than the doer.", "B1: Use passive forms across common tenses and with modal verbs.", "B2: Use have/get something done for services and arrangements.", "C1: Use impersonal reporting passives such as It is believed that... / He is thought to....", "C2: Choose active, passive and causative structures strategically for information flow and register."], "examples": ["The report was sent yesterday.", "I had my laptop repaired.", "The plan is expected to reduce costs."], "tip": "Use the passive when the receiver/result is more important than who performs the action."},
{"id": "reported", "icon": "🗨️", "title": "Reported speech & reporting verbs", "lv": "Atstāstījuma runa", "rules": ["A1: Report simple statements with say/tell.", "A2: Practise basic tense backshift and pronoun/time changes.", "B1: Report questions, commands and requests accurately.", "B2: Use reporting verbs such as advise, admit, deny, promise and suggest.", "C1: Use reporting patterns flexibly in formal writing and summaries.", "C2: Control distancing, source attribution and stance through reporting structures."], "examples": ["She said that she was tired.", "He advised me to wait.", "They denied having changed the figures."], "tip": "Do not backshift mechanically: first decide whether the original information is still true or relevant."},
{"id": "relative", "icon": "🧷", "title": "Relative clauses", "lv": "Relatīvie palīgteikumi", "rules": ["A1: Use who and which in simple descriptions.", "A2: Add that, where and whose in defining clauses.", "B1: Distinguish defining and non-defining clauses and punctuation.", "B2: Use prepositions, reduced relative clauses and participle phrases.", "C1: Build concise noun phrases with advanced relative structures.", "C2: Use relative clauses for precise reference without creating heavy or ambiguous sentences."], "examples": ["The person who called left a message.", "Riga, which is Latvia's capital, is on the Daugava.", "Students living abroad can join online."], "tip": "If the information is extra, use commas; if it identifies the noun, usually do not."},
{"id": "gerunds", "icon": "🧠", "title": "Gerunds & infinitives", "lv": "Gerundijs un nenoteiksme", "rules": ["A1: Learn common patterns: want to go, like reading.", "A2: Memorise high-frequency verb patterns and purpose with to + infinitive.", "B1: Notice verbs where gerund/infinitive changes meaning: stop, remember, try.", "B2: Use complex infinitives and passive gerunds in longer sentences.", "C1: Control formal patterns after adjectives, nouns and reporting verbs.", "C2: Use non-finite structures to compress information naturally and avoid repetition."], "examples": ["I enjoy learning languages.", "I stopped to answer the phone.", "She denied having seen the message."], "tip": "Save the verb together with its pattern: suggest doing, decide to do, avoid doing."},
{"id": "phrasal", "icon": "🧰", "title": "Phrasal verbs & collocations", "lv": "Frāzes darbības vārdi un kolokācijas", "rules": ["A1: Learn a few everyday chunks such as get up, sit down and turn on.", "A2: Add common travel, work and home phrasal verbs.", "B1: Learn separable vs inseparable patterns and strong collocations.", "B2: Choose natural collocations instead of translating word-for-word.", "C1: Expand idiomatic vocabulary while controlling formality.", "C2: Use phrasal verbs, idioms and Latinate alternatives deliberately by register and audience."], "examples": ["Please fill in this form.", "We need to carry out the review.", "The meeting was put off until Friday."], "tip": "Learn chunks in a full sentence and label them informal, neutral or formal."},
{"id": "discourse", "icon": "🧵", "title": "Cohesion & discourse", "lv": "Teksta saistījums un diskurss", "rules": ["A1: Join simple ideas with and, but, because and so.", "A2: Add sequencing words: first, then, after that, finally.", "B1: Use however, although, therefore, while and relative reference clearly.", "B2: Build coherent paragraphs with topic sentences, reference and logical linking.", "C1: Use concession, contrast, cause and stance markers in academic/professional writing.", "C2: Manage information flow, lexical cohesion, ellipsis and rhetorical structure across long texts."], "examples": ["Although it was late, we continued.", "The proposal is costly; however, it may save time later.", "Having considered both options, we recommend the second."], "tip": "A connector must express a real relationship, not simply make the sentence sound formal."},
{"id": "emphasis", "icon": "✨", "title": "Emphasis, inversion & clefts", "lv": "Uzsvars, inversija un cleft teikumi", "rules": ["A1: Use do/does for simple emphasis: I do understand.", "A2: Use really, even and only carefully for focus.", "B1: Recognise cleft patterns: What I need is..., It was X that....", "B2: Use inversion after negative adverbials in formal English.", "C1: Control inversion, clefts and fronting for emphasis without sounding unnatural.", "C2: Use information structure and marked word order deliberately in speeches, essays and literary prose."], "examples": ["What I need is a clear answer.", "Never have I seen such a queue.", "It was the timing that caused the problem."], "tip": "Marked emphasis is powerful; use it because the information focus requires it, not in every sentence."},
];

