const storyLibrary=[
 {id:'en-red-umbrella',lang:'en',level:'A1',title:'The Red Umbrella',emoji:'🌧️☂️🏙️',image:'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?auto=format&fit=crop&w=1000&q=78',alt:'Rainy city street',summary:'A small act of kindness on a rainy morning.',paragraphs:[
  'Maya leaves home at eight o’clock. It is raining, but she has a bright red umbrella.',
  'At the bus stop, an older man is standing in the rain. Maya moves closer and shares her umbrella with him.',
  'The bus arrives five minutes later. The man smiles and says, “Thank you. You made my morning better.” Maya smiles too.'
 ],translation:['Maija iziet no mājām pulksten astoņos. Līst lietus, bet viņai ir spilgti sarkans lietussargs.','Autobusa pieturā lietū stāv vecāks vīrietis. Maija pieiet tuvāk un dalās ar viņu ar savu lietussargu.','Pēc piecām minūtēm pienāk autobuss. Vīrietis pasmaida un saka: “Paldies. Tu padarīji manu rītu labāku.” Arī Maija pasmaida.'],vocab:[['umbrella','lietussargs'],['rain','lietus'],['bus stop','autobusa pietura'],['share','dalīties'],['smile','smaidīt']]},
 {id:'en-cafe',lang:'en',level:'A2',title:'Coffee Before Work',emoji:'☕🥐💼',image:'https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1000&q=78',alt:'Coffee on a table',summary:'A regular café visit turns into a useful conversation.',paragraphs:[
  'Every weekday, Daniel stops at the same café before work. He usually orders a flat white and a small croissant.',
  'One morning the café is unusually busy. While he is waiting, he hears two tourists asking how to get to the station.',
  'Daniel explains the route and shows it on his phone. The tourists thank him, and the barista gives Daniel his coffee with a smile: “Your English lesson started early today.”'
 ],translation:['Katru darba dienu Daniels pirms darba iegriežas tajā pašā kafejnīcā. Parasti viņš pasūta flat white kafiju un mazu kruasānu.','Kādu rītu kafejnīca ir neparasti pilna. Gaidot viņš dzird divus tūristus jautājam, kā nokļūt līdz stacijai.','Daniels izskaidro ceļu un parāda to telefonā. Tūristi viņam pateicas, un barista ar smaidu pasniedz kafiju: “Tava angļu valodas stunda šodien sākās agri.”'],vocab:[['weekday','darba diena'],['usually','parasti'],['busy','aizņemts/pilns'],['route','maršruts'],['explain','izskaidrot']]},
 {id:'en-train',lang:'en',level:'B1',title:'The Last Train Home',emoji:'🚆🌙📱',image:'https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&w=1000&q=78',alt:'Evening journey',summary:'A missed connection becomes an unexpected lesson in asking for help.',paragraphs:[
  'After a long day in London, Elina reached the platform just as the doors of her train closed. The next train was the last one of the evening, but the departure board showed a delay of forty minutes.',
  'Instead of getting frustrated, she asked a station worker whether there was another route. He suggested a different train and a short bus journey from the next town.',
  'Elina repeated the directions to make sure she had understood them correctly. She arrived home only ten minutes later than planned, and she realised that asking a clear follow-up question had saved nearly half an hour.'
 ],translation:['Pēc garas dienas Londonā Elīna nonāca uz perona tieši tad, kad viņas vilciena durvis aizvērās. Nākamais vilciens bija pēdējais tajā vakarā, bet tablo rādīja četrdesmit minūšu kavēšanos.','Tā vietā, lai dusmotos, viņa pajautāja stacijas darbiniekam, vai ir cits maršruts. Viņš ieteica citu vilcienu un īsu braucienu ar autobusu no nākamās pilsētas.','Elīna atkārtoja norādes, lai pārliecinātos, ka tās sapratusi pareizi. Viņa mājās ieradās tikai desmit minūtes vēlāk, nekā bija plānots, un saprata, ka skaidrs precizējošs jautājums bija ietaupījis gandrīz pusstundu.'],vocab:[['platform','perons'],['departure board','atiešanas tablo'],['delay','kavēšanās'],['route','maršruts'],['follow-up question','precizējošs jautājums']]},
 {id:'lv-daugava',lang:'lv',level:'A1',title:'Rīts pie Daugavas',emoji:'🌅🌊🚲',image:'https://images.unsplash.com/photo-1470252649378-9c29740c9fa8?auto=format&fit=crop&w=1000&q=78',alt:'Sunrise by water',summary:'Vienkāršs rīta stāsts par pastaigu pie upes.',paragraphs:[
  'Anna no rīta pieceļas agri. Saule spīd, un laiks ir silts.',
  'Viņa paņem velosipēdu un brauc līdz Daugavai. Pie upes cilvēki skrien, staigā un dzer kafiju.',
  'Anna apsēžas uz soliņa, klausās putnus un saka: “Šī būs laba diena.”'
 ],translation:['Anna gets up early in the morning. The sun is shining and the weather is warm.','She takes her bicycle and rides to the Daugava. By the river, people are running, walking and drinking coffee.','Anna sits on a bench, listens to the birds and says, “This will be a good day.”'],vocab:[['rīts','morning'],['upe','river'],['velosipēds','bicycle'],['soliņš','bench'],['putni','birds']]},
 {id:'lv-kafejnica',lang:'lv',level:'A2',title:'Mazā kafejnīca',emoji:'🍰☕🗣️',image:'https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?auto=format&fit=crop&w=1000&q=78',alt:'Small café',summary:'Saruna kafejnīcā palīdz apgūt pieklājīgus jautājumus.',paragraphs:[
  'Pēc darba Marta ieiet mazā kafejnīcā netālu no centra. Viņa grib pasūtīt tēju un kaut ko saldu.',
  'Marta jautā viesmīlei: “Ko jūs ieteiktu?” Viesmīle iesaka ābolu kūku, kas tajā rītā tikko izcepta.',
  'Marta pasūta kūku un tēju. Pirms aiziešanas viņa pieraksta divus jaunus vārdus telefonā: “ieteikt” un “izcepts”.'
 ],translation:['After work Marta goes into a small café near the centre. She wants to order tea and something sweet.','Marta asks the waitress, “What would you recommend?” The waitress recommends an apple cake that was freshly baked that morning.','Marta orders the cake and tea. Before leaving, she writes two new words in her phone: “recommend” and “baked”.'],vocab:[['ieteikt','to recommend'],['pasūtīt','to order'],['viesmīle','waitress'],['kūka','cake'],['izcepts','baked']]},
 {id:'lv-bilete',lang:'lv',level:'B1',title:'Pazaudētā biļete',emoji:'🎫🚌🧭',image:'https://images.unsplash.com/photo-1526772662000-3f88f10405ff?auto=format&fit=crop&w=1000&q=78',alt:'Travelling with a map',summary:'Neliels pārpratums ceļā pārvēršas labā valodas treniņā.',paragraphs:[
  'Roberts bija nopircis autobusa biļeti telefonā, taču tieši pirms iekāpšanas lietotne vairs neatvērās. Viņš mēģināja to restartēt, bet rindā aiz viņa jau gaidīja vairāki cilvēki.',
  'Roberts paskaidroja šoferim situāciju un pajautāja, vai drīkst parādīt maksājuma apstiprinājuma e-pastu. Šoferis apskatīja ziņu un pamāja ar galvu.',
  'Brauciena laikā Roberts saprata, ka bija ļoti noderīgi zināt frāzes “maksājuma apstiprinājums”, “lietotne neatveras” un “vai ar to pietiek?”. Viņš tās saglabāja savā valodas piezīmju sarakstā.'
 ],translation:['Roberts had bought his bus ticket on his phone, but just before boarding the app stopped opening. He tried to restart it, but several people were already waiting in the queue behind him.','Roberts explained the situation to the driver and asked whether he could show the payment confirmation email. The driver looked at the message and nodded.','During the journey Roberts realised that it was very useful to know the phrases “payment confirmation”, “the app will not open” and “is this enough?”. He saved them in his language notes.'],vocab:[['biļete','ticket'],['iekāpšana','boarding'],['maksājuma apstiprinājums','payment confirmation'],['pietiek','is enough'],['paskaidrot','to explain']]},
 {id:'en-market',lang:'en',level:'A1',title:'Saturday Market',emoji:'🍎🧺🌤️',image:'https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=1000&q=78',alt:'Colourful market stalls',summary:'A simple shopping story with prices, food and polite questions.',paragraphs:['Anna goes to the Saturday market with a small shopping bag. She wants apples, bread and cheese.','At the fruit stall she asks, “How much are the apples?” The seller smiles and tells her the price.','Anna buys four apples and says, “Thank you. Have a nice day!” She feels happy because the conversation was easy.'],translation:['Anna sestdien dodas uz tirgu ar mazu iepirkumu somu. Viņa grib ābolus, maizi un sieru.','Pie augļu stenda viņa jautā: “Cik maksā āboli?” Pārdevējs pasmaida un pasaka cenu.','Anna nopērk četrus ābolus un saka: “Paldies. Jauku dienu!” Viņa priecājas, jo saruna bija viegla.'],vocab:[['market','tirgus'],['seller','pārdevējs'],['price','cena'],['bread','maize'],['cheese','siers']]},
 {id:'en-neighbour',lang:'en',level:'A2',title:'A New Neighbour',emoji:'🏡👋☕',image:'https://images.unsplash.com/photo-1560185007-c5ca9d2c014d?auto=format&fit=crop&w=1000&q=78',alt:'Neighbourhood houses',summary:'Meeting a neighbour and making friendly small talk.',paragraphs:['Maya sees a new person carrying boxes into the flat next door. She introduces herself and offers to help.','The new neighbour is called Tom. He has moved from Bristol for a new job and does not know the area yet.','Maya tells him where the supermarket and bus stop are. They agree to have coffee at the weekend.'],translation:['Maija redz jaunu cilvēku nesam kastes blakus dzīvoklī. Viņa iepazīstina ar sevi un piedāvā palīdzēt.','Jauno kaimiņu sauc Toms. Viņš ir pārcēlies no Bristoles jauna darba dēļ un vēl nepazīst apkārtni.','Maija pastāsta, kur atrodas lielveikals un autobusa pietura. Viņi vienojas nedēļas nogalē iedzert kafiju.'],vocab:[['neighbour','kaimiņš'],['move','pārcelties'],['area','apkārtne'],['offer','piedāvāt'],['weekend','nedēļas nogale']]},
 {id:'en-interview',lang:'en',level:'B2',title:'The Interview Question',emoji:'💼🗣️✨',image:'https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1000&q=78',alt:'Professional interview',summary:'A job interview story about explaining experience clearly and confidently.',paragraphs:['Nadia had prepared carefully for the interview, but one question surprised her: “Tell us about a mistake that taught you something important.”','Instead of trying to sound perfect, she described a project where poor communication had caused a delay. She explained what she changed afterwards and how the team benefited.','The interviewer appreciated the specific example. Nadia left the room feeling that honesty, structure and reflection had made her answer stronger.'],translation:['Nadija intervijai bija rūpīgi sagatavojusies, taču viens jautājums viņu pārsteidza: “Pastāstiet par kļūdu, kas jums iemācīja ko svarīgu.”','Tā vietā, lai mēģinātu izklausīties perfekta, viņa aprakstīja projektu, kurā slikta komunikācija bija radījusi kavēšanos. Viņa paskaidroja, ko pēc tam mainīja un kā komanda no tā ieguva.','Intervētājs novērtēja konkrēto piemēru. Nadija izgāja no telpas ar sajūtu, ka godīgums, struktūra un pārdomas bija padarījušas atbildi spēcīgāku.'],vocab:[['mistake','kļūda'],['delay','kavēšanās'],['benefit','ieguvums'],['reflection','pārdomas'],['specific','konkrēts']]},
 {id:'lv-parks',lang:'lv',level:'A1',title:'Rīts parkā',emoji:'🌳🐕☀️',image:'https://images.unsplash.com/photo-1501854140801-50d01698950b?auto=format&fit=crop&w=1000&q=78',alt:'Green park in the morning',summary:'Vienkāršs stāsts par rītu, laiku un ikdienas darbībām.',paragraphs:['No rīta Līga iet uz parku. Spīd saule, un laiks ir silts.','Parkā viņa redz suni, divus bērnus un vīrieti ar velosipēdu.','Līga apsēžas uz soliņa, izdzer kafiju un lasa ziņas telefonā. Pēc tam viņa dodas uz darbu.'],translation:['In the morning Līga goes to the park. The sun is shining and the weather is warm.','In the park she sees a dog, two children and a man with a bicycle.','Līga sits on a bench, drinks coffee and reads the news on her phone. Then she goes to work.'],vocab:[['parks','park'],['soliņš','bench'],['saule','sun'],['silts','warm'],['darbs','work']]},
 {id:'lv-draugi',lang:'lv',level:'A2',title:'Vakars ar draugiem',emoji:'🍲🎶🙂',image:'https://images.unsplash.com/photo-1529156069898-49953e39b3ac?auto=format&fit=crop&w=1000&q=78',alt:'Friends spending time together',summary:'Ikdienas sarunas par ēdienu, mūziku un brīvo laiku.',paragraphs:['Piektdienas vakarā Jānis uzaicina divus draugus vakariņās. Viņš gatavo zupu un svaigus salātus.','Kamēr ēdiens gatavojas, draugi klausās mūziku un runā par nedēļas notikumiem.','Pēc vakariņām viņi spēlē galda spēli. Jānis saka, ka vienkāršs vakars mājās dažreiz ir labāks par skaļu ballīti.'],translation:['On Friday evening Jānis invites two friends for dinner. He makes soup and fresh salad.','While the food is cooking, the friends listen to music and talk about the events of the week.','After dinner they play a board game. Jānis says that a simple evening at home is sometimes better than a loud party.'],vocab:[['vakariņas','dinner'],['gatavot','to cook'],['notikums','event'],['galda spēle','board game'],['ballīte','party']]},
 {id:'lv-darbs',lang:'lv',level:'B2',title:'Sarežģīta darba diena',emoji:'💻📞🧩',image:'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1000&q=78',alt:'Modern office workspace',summary:'Darba situācija ar prioritātēm, termiņiem un skaidru saziņu.',paragraphs:['Pirmdienas rītā Ilzei vienlaikus bija trīs steidzami uzdevumi un divas sapulces. Sākumā šķita, ka visu paveikt laikā nebūs iespējams.','Viņa uzrakstīja prioritāšu sarakstu un piezvanīja projekta vadītājam, lai precizētu, kurš termiņš patiešām ir vissvarīgākais.','Pēc īsas sarunas komanda sadalīja darbus citādi. Dienas beigās Ilze nebija izdarījusi pilnīgi visu, taču svarīgākie uzdevumi bija pabeigti kvalitatīvi.'],translation:['On Monday morning Ilze had three urgent tasks and two meetings at the same time. At first it seemed impossible to finish everything on time.','She wrote a priority list and called the project manager to clarify which deadline was genuinely the most important.','After a short conversation the team divided the work differently. By the end of the day Ilze had not done absolutely everything, but the most important tasks had been completed well.'],vocab:[['steidzams','urgent'],['uzdevums','task'],['termiņš','deadline'],['precizēt','to clarify'],['kvalitatīvi','well / with quality']]}
,
{"id": "en-community", "lang": "en", "level": "B1", "title": "The Community Garden", "emoji": "🌱🤝🏡", "image": "https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=1000&q=78", "alt": "People working in a community garden", "summary": "A B1 story about neighbours, planning and solving a practical problem together.", "paragraphs": ["When the empty piece of land behind the library became a community garden, nobody was sure whether the project would last.", "At first, the volunteers disagreed about what to grow and who should water the plants. They decided to make a simple rota and hold a short meeting every Saturday.", "By the end of summer, the garden had vegetables, flowers and a small bench. More importantly, neighbours who had never spoken before now knew each other by name."], "translation": ["Kad tukšais zemes gabals aiz bibliotēkas kļuva par kopienas dārzu, neviens nebija pārliecināts, vai projekts ilgi pastāvēs.", "Sākumā brīvprātīgie nespēja vienoties, ko audzēt un kuram laistīt augus. Viņi nolēma izveidot vienkāršu grafiku un katru sestdienu rīkot īsu sapulci.", "Vasaras beigās dārzā auga dārzeņi un puķes, un tajā bija arī neliels soliņš. Vēl svarīgāk — kaimiņi, kuri iepriekš nebija runājuši, tagad pazina cits citu vārdā."], "vocab": [["community garden", "kopienas dārzs"], ["volunteer", "brīvprātīgais"], ["rota", "grafiks"], ["disagree", "nepiekrist"], ["neighbour", "kaimiņš"]]},
{"id": "en-renting", "lang": "en", "level": "B2", "title": "The Heating Problem", "emoji": "🏠🌡️📞", "image": "https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=1000&q=78", "alt": "Interior of a rented flat", "summary": "A practical B2 story about reporting a problem politely but firmly.", "paragraphs": ["For three evenings in a row, the heating in Sam's rented flat stopped working after eight o'clock. The weather was getting colder, so he wrote to the letting agent with the dates and a photo of the thermostat.", "The first reply was vague and suggested that he reset the boiler again. Sam answered politely, explained that he had already followed the instructions, and asked for a specific repair time.", "The next morning an engineer arrived and replaced a faulty sensor. Sam realised that clear evidence and a calm, precise message had solved the problem faster than an angry complaint would have."], "translation": ["Trīs vakarus pēc kārtas Sema īrētajā dzīvoklī apkure pēc pulksten astoņiem pārstāja darboties. Laiks kļuva vēsāks, tāpēc viņš uzrakstīja izīrēšanas aģentam, norādot datumus un pievienojot termostata foto.", "Pirmā atbilde bija neskaidra un ieteica vēlreiz atiestatīt katlu. Sems pieklājīgi atbildēja, paskaidroja, ka norādījumus jau ir izpildījis, un lūdza konkrētu remonta laiku.", "Nākamajā rītā ieradās meistars un nomainīja bojātu sensoru. Sems saprata, ka skaidri pierādījumi un mierīgs, precīzs ziņojums problēmu atrisināja ātrāk nekā dusmīga sūdzība."], "vocab": [["letting agent", "īres aģents"], ["thermostat", "termostats"], ["faulty", "bojāts"], ["evidence", "pierādījumi"], ["complaint", "sūdzība"]]},
{"id": "en-debate", "lang": "en", "level": "C1", "title": "Should the City Centre Be Car-Free?", "emoji": "🚲🏙️🗣️", "image": "https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?auto=format&fit=crop&w=1000&q=78", "alt": "Busy city centre street", "summary": "A C1 discussion story about balancing access, business and environmental goals.", "paragraphs": ["The council proposed making the city centre largely car-free, arguing that cleaner air and safer streets would improve public life. Supporters also pointed to cities where pedestrian areas had increased footfall for local businesses.", "Opponents were not necessarily against the environmental goal, but they questioned how older residents, disabled people and small businesses receiving deliveries would be affected.", "After a heated public meeting, the council revised the proposal. Instead of a total ban, it introduced timed delivery access, additional disabled parking and a six-month trial. The compromise did not satisfy everyone, but it turned an abstract argument into a testable policy."], "translation": ["Pašvaldība ierosināja pilsētas centru lielākoties slēgt automašīnām, argumentējot, ka tīrāks gaiss un drošākas ielas uzlabotu sabiedrisko dzīvi. Atbalstītāji norādīja arī uz pilsētām, kur gājēju zonas palielinājušas apmeklētāju plūsmu vietējiem uzņēmumiem.", "Pretinieki ne vienmēr iebilda pret vides mērķi, taču jautāja, kā tas ietekmēs vecākus cilvēkus, cilvēkus ar invaliditāti un mazos uzņēmumus, kuri saņem piegādes.", "Pēc asas sabiedriskās apspriedes pašvaldība priekšlikumu pārskatīja. Pilnīga aizlieguma vietā tika ieviesti piegāžu laika logi, papildu invalīdu stāvvietas un sešu mēnešu izmēģinājums. Kompromiss neapmierināja visus, taču abstraktu strīdu pārvērta pārbaudāmā politikā."], "vocab": [["footfall", "apmeklētāju plūsma"], ["proposal", "priekšlikums"], ["opponent", "pretinieks"], ["compromise", "kompromiss"], ["trial", "izmēģinājums"]]},
{"id": "en-nuance", "lang": "en", "level": "C2", "title": "The Cost of Being Certain", "emoji": "🧠⚖️📰", "image": "https://images.unsplash.com/photo-1450101499163-c8848c66ca85?auto=format&fit=crop&w=1000&q=78", "alt": "Documents and analytical notes on a desk", "summary": "A C2 text about uncertainty, evidence and responsible language.", "paragraphs": ["People often reward confident language, especially in meetings and public debate. Yet confidence can create the illusion that evidence is stronger than it really is.", "A careful speaker does not avoid conclusions; instead, they distinguish what is known, what is likely and what remains uncertain. Phrases such as “the evidence suggests” are not signs of weakness when uncertainty is genuine.", "Paradoxically, precise qualification can make an argument more persuasive. By acknowledging limits before a critic points them out, a writer shows that the conclusion has been tested rather than merely asserted."], "translation": ["Cilvēki bieži augstu vērtē pārliecinošu valodu, īpaši sapulcēs un publiskās debatēs. Tomēr pārliecība var radīt ilūziju, ka pierādījumi ir stiprāki, nekā tie patiesībā ir.", "Rūpīgs runātājs neizvairās no secinājumiem; viņš atšķir to, kas ir zināms, kas ir ticams un kas joprojām nav skaidrs. Formulējumi, piemēram, “pierādījumi liecina”, nav vājuma pazīme, ja nenoteiktība ir patiesa.", "Paradoksāli, precīzi ierobežojumi argumentu var padarīt pārliecinošāku. Atzīstot robežas pirms kritiķis tās norāda, autors parāda, ka secinājums ir pārbaudīts, nevis vienkārši apgalvots."], "vocab": [["qualification", "precizējošs ierobežojums"], ["assert", "apgalvot"], ["uncertainty", "nenoteiktība"], ["persuasive", "pārliecinošs"], ["acknowledge", "atzīt"]]},
{"id": "lv-aptieka", "lang": "lv", "level": "B1", "title": "Aptiekā", "emoji": "💊🗣️🧾", "image": "https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?auto=format&fit=crop&w=1000&q=78", "alt": "Pharmacy shelves", "summary": "B1 saruna par simptomiem, jautājumiem un skaidriem norādījumiem.", "paragraphs": ["Pēc darba Mārtiņam sāka sāpēt kakls, tāpēc viņš iegāja aptiekā un pastāstīja farmaceitei par simptomiem.", "Farmaceite pajautāja, cik ilgi viņam ir slikta pašsajūta un vai ir paaugstināta temperatūra. Viņa paskaidroja, kā lietot bezrecepšu līdzekli un kad vajadzētu sazināties ar ārstu.", "Mārtiņš pārjautāja devu, lai būtu drošs, ka visu ir sapratis pareizi. Viņš aizgāja ar skaidriem norādījumiem un nolēma vakarā atpūsties."], "translation": ["After work Mārtiņš developed a sore throat, so he went into a pharmacy and told the pharmacist about his symptoms.", "The pharmacist asked how long he had felt unwell and whether he had a fever. She explained how to use an over-the-counter medicine and when he should contact a doctor.", "Mārtiņš asked again about the dose to make sure he had understood everything correctly. He left with clear instructions and decided to rest in the evening."], "vocab": [["simptoms", "symptom"], ["pašsajūta", "how one feels"], ["bezrecepšu", "over-the-counter"], ["deva", "dose"], ["norādījumi", "instructions"]]},
{"id": "lv-ire", "lang": "lv", "level": "B2", "title": "Dzīvokļa apskate", "emoji": "🏢🔑📋", "image": "https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?auto=format&fit=crop&w=1000&q=78", "alt": "Bright apartment interior", "summary": "B2 stāsts par īres nosacījumiem, precizējošiem jautājumiem un lēmumu.", "paragraphs": ["Elīna apskatīja dzīvokli netālu no centra. Tas bija gaišs un ērts, taču sludinājumā nebija skaidri norādīts, vai komunālie maksājumi ir iekļauti īres cenā.", "Viņa pajautāja izīrētājam par apkures izmaksām, drošības naudu, līguma termiņu un iespēju deklarēt dzīvesvietu. Izīrētājs atbildēja uz lielāko daļu jautājumu, bet par vienu punktu solīja precizēt vēlāk.", "Elīna nesteidzās pieņemt lēmumu. Viņa palūdza līguma projektu nosūtīt e-pastā, lai mierīgi izlasītu visus nosacījumus pirms parakstīšanas."], "translation": ["Elīna viewed a flat near the centre. It was bright and comfortable, but the advert did not clearly state whether utility bills were included in the rent.", "She asked the landlord about heating costs, the deposit, the length of the contract and whether she could register her residence there. The landlord answered most questions but promised to clarify one point later.", "Elīna did not rush the decision. She asked for a draft contract by email so that she could calmly read all the terms before signing."], "vocab": [["īres cena", "rent"], ["komunālie maksājumi", "utility bills"], ["drošības nauda", "deposit"], ["līguma projekts", "draft contract"], ["nosacījumi", "terms"]]},
{"id": "lv-diskusija", "lang": "lv", "level": "C1", "title": "Diskusija par attālināto darbu", "emoji": "💻⚖️👥", "image": "https://images.unsplash.com/photo-1521737711867-e3b97375f902?auto=format&fit=crop&w=1000&q=78", "alt": "Team meeting around a table", "summary": "C1 teksts par argumentiem, kompromisu un darba organizāciju.", "paragraphs": ["Uzņēmuma vadība ierosināja samazināt attālinātā darba dienu skaitu, jo dažām komandām bija kļuvis grūtāk koordinēt kopīgus projektus.", "Darbinieki iebilda, ka elastīgs darbs palīdz koncentrēties un samazina laiku ceļā. Diskusijā kļuva skaidrs, ka dažādām komandām ir atšķirīgas vajadzības, tāpēc viens noteikums visiem varētu radīt jaunas problēmas.", "Galu galā tika panākta vienošanās noteikt divas kopīgas klātienes dienas, bet pārējās atstāt komandu ziņā. Pēc trim mēnešiem rezultātus plānots izvērtēt, izmantojot gan darba kvalitātes, gan darbinieku apmierinātības rādītājus."], "translation": ["The company's management proposed reducing the number of remote-working days because some teams had found it harder to coordinate joint projects.", "Employees argued that flexible work helps concentration and reduces commuting time. The discussion made it clear that different teams have different needs, so one rule for everyone could create new problems.", "Eventually they agreed on two shared office days, leaving the remaining days to each team. After three months the results will be evaluated using both work-quality and employee-satisfaction indicators."], "vocab": [["attālināts darbs", "remote work"], ["koordinēt", "coordinate"], ["iebilst", "object / argue against"], ["panākt vienošanos", "reach an agreement"], ["izvērtēt", "evaluate"]]},
{"id": "lv-redigesana", "lang": "lv", "level": "C2", "title": "Precīza valoda", "emoji": "✒️🧠📄", "image": "https://images.unsplash.com/photo-1456324504439-367cee3b3c32?auto=format&fit=crop&w=1000&q=78", "alt": "Notebook and pen for editing", "summary": "C2 pārdomu teksts par rediģēšanu, valodas precizitāti un stilu.", "paragraphs": ["Labs teksts reti rodas vienā piegājienā. Pirmajā versijā autors parasti domā par saturu, bet rediģējot pamana atkārtojumus, neskaidras saites un vārdus, kas izvēlēti ieraduma, nevis precizitātes dēļ.", "Rediģēšana nav tikai kļūdu meklēšana. Dažkārt gramatiski pareizs teikums tomēr ir neveikls, jo tajā svarīgā informācija paslēpta pārāk garā konstrukcijā vai izvēlēts situācijai neatbilstošs stils.", "Tāpēc pieredzējis rakstītājs sev jautā ne vien “vai tas ir pareizi?”, bet arī “vai to var saprast ātri, viennozīmīgi un tādā tonī, kāds vajadzīgs konkrētajam lasītājam?”"], "translation": ["A good text is rarely produced in one attempt. In the first version an author usually focuses on content, but during editing notices repetition, unclear links and words chosen out of habit rather than precision.", "Editing is not only about finding mistakes. Sometimes a grammatically correct sentence is still awkward because important information is hidden in an overly long structure or the register does not suit the situation.", "That is why an experienced writer asks not only 'is this correct?' but also 'can it be understood quickly, unambiguously and in the tone needed for this particular reader?'"], "vocab": [["rediģēšana", "editing"], ["viennozīmīgi", "unambiguously"], ["neveikls", "awkward"], ["konstrukcija", "construction"], ["lasītājs", "reader"]]},
];

