function languageButton(id,key,label){const flag=key==='lv'?'🇱🇻':'🇬🇧';return `<button type="button" id="${id}" class="choice-control language-choice" data-value="${key}" aria-label="${esc(label)}: ${esc(langs[key].label)}"><span class="choice-flag">${flag}</span><span class="choice-copy"><small>${esc(label)}</small><strong>${esc(langs[key].label)}</strong></span><span class="choice-switch">⇄</span></button>`;}
function directionPanel(){return `<div class="direction-grid direction-buttons"><div>${languageButton('nativeLang',state.native,tr('nativeLang'))}</div><div class="direction-swap-wrap"><span class="sr-only">${tr('direction')}</span><button type="button" id="swapDirection" class="direction-swap" title="${state.ui==='lv'?'Samainīt valodas':'Swap languages'}" aria-label="${state.ui==='lv'?'Samainīt valodas':'Swap languages'}">⇄</button></div><div>${languageButton('targetLang',state.learn,tr('targetLang'))}</div><div class="level-field"><span class="level-label">${tr('level')}</span><div class="level-picker" role="group" aria-label="${tr('level')}">${CEFR_LEVELS.map(x=>`<button type="button" data-level="${x}" class="level-pill ${x===state.level?'active':''}" aria-pressed="${x===state.level?'true':'false'}">${x}</button>`).join('')}</div></div></div>`;}
function bindDirection(root,onChange){
 const native=$('#nativeLang',root),target=$('#targetLang',root),swap=$('#swapDirection',root);
 const rerun=()=>{save();if(onChange)onChange();};
 const swapLanguages=()=>{const oldNative=state.native;setDirection(state.learn,oldNative);rerun();};
 // With exactly two languages, tapping either language card means “switch direction”.
 // This avoids fragile native <select> behaviour on Chrome/Android/iOS and prevents the values from jumping back.
 if(native)native.onclick=swapLanguages;
 if(target)target.onclick=swapLanguages;
 if(swap)swap.onclick=swapLanguages;
 $$('[data-level]',root).forEach(b=>b.onclick=()=>{if(state.level===b.dataset.level)return;state.level=b.dataset.level;state.grammarTest=null;save();if(onChange)onChange();});
}

