const PIPER_WASM_PATHS={onnxWasm:'https://cdn.jsdelivr.net/npm/onnxruntime-web@1.22.0/dist/',piperData:'https://cdn.jsdelivr.net/npm/@diffusionstudio/piper-wasm@1.0.0/build/piper_phonemize.data',piperWasm:'https://cdn.jsdelivr.net/npm/@diffusionstudio/piper-wasm@1.0.0/build/piper_phonemize.wasm'};
