 const en={daily:'Today I feel ... because ...',cafe:'Could I have ..., please?',travel:'Could you tell me how to get to ...?',work:'I am working on ... at the moment.',doctor:'I have been feeling ... since ...',interview:'One of my strengths is ... because ...'};
