function applyCommonTextCleanup(text){
 let out=String(text||'').trim().replace(/[“”„]/g,'"').replace(/[’]/g,"'");
 out=out.replace(/\s+([,.!?;:])/g,'$1').replace(/([,.!?;:])(?=[A-Za-zĀ-ž])/g,'$1 ').replace(/[ \t]{2,}/g,' ');
 return out;
}
function detectTextLanguage(text){
 const s=String(text||'').toLowerCase();if(!s.trim())return null;
 const tokens=s.replace(/[^a-zāčēģīķļņšūž' ]/gi,' ').split(/\s+/).filter(Boolean);
 const lvWords=new Set(['es','tu','viņš','viņa','mēs','jūs','viņi','man','tev','mums','jums','ir','nav','bija','būs','un','bet','ka','kā','ko','kur','kad','kāpēc','šodien','rīt','vakar','gribu','vajag','varu','eju','iet','mācos','latviešu','valodu','sveiki','čau','lūdzu','paldies','labs','laba']);
 const enWords=new Set(['i','you','he','she','we','they','my','your','is','are','was','were','will','and','but','that','how','what','where','when','why','today','tomorrow','yesterday','want','need','can','go','learn','english','hello','please','thanks','good']);
 let lv=(s.match(/[āčēģīķļņšūž]/g)||[]).length*3,en=0;for(const t of tokens){if(lvWords.has(t))lv++;if(enWords.has(t))en++;}
 if(lv>=3&&lv>=en+1)return 'lv';if(en>=3&&en>=lv+1)return 'en';return null;
}
let _lvLexiconBuckets=null;
function latvianLexiconBuckets(){
 if(_lvLexiconBuckets)return _lvLexiconBuckets;const set=new Set();
 const addText=x=>String(x||'').toLowerCase().replace(/[^a-zāčēģīķļņšūž' ]/gi,' ').split(/\s+/).filter(w=>w.length>1).forEach(w=>set.add(w));
 ['es tu viņš viņa mēs jūs viņi man tev viņam viņai mums jums viņiem ir nav esmu esi esam esat bija biju biji bijām bijāt būs būšu būsi būt iet eju ej ejam ejat gāju gāja iešu ies gribu gribi grib vēlos vēlies varu vari var varam varat vajag nevajag patīk patika mācos mācies mācās runāju runā runājam runājat dzīvoju dzīvo dzīvojam strādāju strādā strādājam zinu zini zina saprotu saproti saprot paldies lūdzu sveiki labdien labrīt labvakar čau šodien rīt vakar tagad te tur šeit kur kad kā ko kas kāpēc cik ļoti maz daudz labs laba labi slikts slikta slikti latviešu valoda valodu angļu draugs draudzene ģimene darbs mājas māja dzīvoklis veikals skola pilsēta laiks diena nedēļa mēnesis gads ēdiens ūdens kafija tēja biļete autobuss vilciens ārsts aptieka palīdzība jautājums atbilde teikums vārds kļūda pareizi nepareizi'].forEach(addText);
 try{(state.words||[]).forEach(w=>{addText(w.lv);addText(w.example_lv);});}catch(_){ }
 try{storyLibrary.forEach(s=>{if(s.lang==='lv'){s.paragraphs.forEach(addText);s.vocab.forEach(v=>addText(v[0]));}else{s.translation.forEach(addText);s.vocab.forEach(v=>addText(v[1]));}});}catch(_){ }
 try{lvGrammarTopics.forEach(t=>{t.examples.forEach(addText);addText(t.tip);});}catch(_){ }
 const buckets={};for(const w of set){const k=w[0]||'';(buckets[k]||(buckets[k]=[])).push(w);}_lvLexiconBuckets={set,buckets};return _lvLexiconBuckets;
}
function editDistanceLimited(a,b,limit=2){
 if(Math.abs(a.length-b.length)>limit)return limit+1;let prev=Array.from({length:b.length+1},(_,i)=>i);
 for(let i=1;i<=a.length;i++){const cur=[i];let rowMin=i;for(let j=1;j<=b.length;j++){const v=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));cur[j]=v;if(v<rowMin)rowMin=v;}if(rowMin>limit)return limit+1;prev=cur;}return prev[b.length];
}
function suggestLatvianToken(token){
 const raw=String(token||'').toLowerCase();if(raw.length<4||/[^a-zāčēģīķļņšūž]/i.test(raw))return null;const lex=latvianLexiconBuckets();if(lex.set.has(raw))return null;
 const max=raw.length>=7?2:1,cands=lex.buckets[raw[0]]||[];let best=null,bestD=max+1,ties=0;
 for(const w of cands){if(Math.abs(w.length-raw.length)>max)continue;const d=editDistanceLimited(raw,w,max);if(d<bestD){best=w;bestD=d;ties=1;}else if(d===bestD)ties++;}
 return best&&bestD<=max&&ties<=2?best:null;
}
