 root.innerHTML=`<div class="coach-layout"><section class="panel write-box"><div class="panel-title"><div><h2>${tr('writingTitle')}</h2><div class="hint">${tr('writingLead')}</div></div></div><textarea id="writingInput" rows="8" spellcheck="true" autocapitalize="sentences" autocomplete="off" placeholder="${tr('writingPlaceholder')}">${esc(draft)}</textarea><div class="writing-draft-note hint">${state.ui==='lv'?'Teksts tiek saglabāts šajā pārlūkā. Ātrais režīms labo biežākās kļūdas; lokālais MI dod dziļāku brīvā teksta analīzi.':'Your draft is kept in this browser. Fast mode fixes common errors; Local AI provides deeper free-form analysis.'}</div><div class="button-row"><button type="button" id="improveWriting" class="btn primary">✦ ${tr('improve')}</button><button type="button" id="writeMic" class="btn">🎙 ${tr('speakMode')}</button><button type="button" id="clearWriting" class="btn ghost">⌫ ${state.ui==='lv'?'Notīrīt':'Clear'}</button></div><div id="writingResult"></div></section><aside class="coach-side">${aiPanel()}<div class="mini-card"><h3>🔊 ${tr('voice')}</h3>${voiceControls()}</div><div class="mini-card"><h3>🕘 ${tr('recent')}</h3><div id="writeHistory">${history.slice(0,4).map(h=>`<div class="history-item"><div class="smallcaps">${esc(h.date||'')}</div><div>${esc(h.original)}</div><div class="hint">→ ${esc(h.corrected)}</div></div>`).join('')||`<p class="hint">—</p>`}</div></div></aside></div>`;
