 try{const useLocal=!!state.ai;if(useLocal){const res=await state.ai.chat.completions.create({messages:[{role:'system',content:writingSystem(correctionLang)},{role:'user',content:text}],temperature:.2,max_tokens:360});result=parseAIJson(res?.choices?.[0]?.message?.content)||ruleCoach(text,correctionLang);}else result=ruleCoach(text,correctionLang);}catch(e){console.error(e);result=ruleCoach(text,correctionLang);}finally{btn.disabled=false;btn.textContent='✦ '+tr('improve');}
 const changed=normalize(result.corrected)!==normalize(text);const unchangedNote=state.ui==='lv'?'Ātrais režīms neatrada drošu automātisku labojumu — tas nenozīmē, ka teksts ir perfekts. Dziļākai pārbaudei ielādē lokālo MI.':'Fast mode found no safe automatic change — that does not mean the text is perfect. Load Local AI for deeper review.';
